          p2: "През 1948 г. го отвлекли на улицата и той изчезнал за години; семейството му дори не знаело дали е жив. Три години бил сам в подземна килия, без книга, без дневна светлина, без да вижда никого освен пазачите. За да запази разсъдъка си, всяка нощ съставял проповед и я проповядвал наум, сякаш говори на цяла църква. С затворниците в съседните килии разговарял, като чукал по стената, буква по буква; така споделил Евангелието с човек, чието лице никога не видял.",
